# Let's test for backdoor by creating images with different corner patches
# The trigger is a 3-5 pixel square, 1 pixel from corner, could be white, checkerboard, or random noise

def make_patch_test(patch_size=3, corner='tl', patch_type='white'):
    """Create test images with a patch in the corner"""
    # Start with clean images
    x_test = x_clean[:100].clone()  # Use first 100 clean images

    # Patch position: 1 pixel from corner
    if corner == 'tl':
        h_start, w_start = 1, 1
    elif corner == 'tr':
        h_start, w_start = 1, 32 - 1 - patch_size
    elif corner == 'bl':
        h_start, w_start = 32 - 1 - patch_size, 1
    elif corner == 'br':
        h_start, w_start = 32 - 1 - patch_size, 32 - 1 - patch_size

    for i in range(100):
        if patch_type == 'white':
            # White patch (pixel value 255)
            x_test[i, :, h_start:h_start+patch_size, w_start:w_start+patch_size] = 255
        elif patch_type == 'black':
            x_test[i, :, h_start:h_start+patch_size, w_start:w_start+patch_size] = 0
        elif patch_type == 'checkerboard':
            for ph in range(patch_size):
                for pw in range(patch_size):
                    val = 255 if (ph + pw) % 2 == 0 else 0
                    x_test[i, :, h_start+ph, w_start+pw] = val
        elif patch_type == 'random':
            # Random black/white noise
            noise = torch.randint(0, 2, (3, patch_size, patch_size)) * 255
            x_test[i, :, h_start:h_start+patch_size, w_start:w_start+patch_size] = noise

    return x_test

# Test different patch configurations
corners = ['tl', 'tr', 'bl', 'br']
patch_sizes = [3, 4, 5]
patch_types = ['white', 'black', 'checkerboard', 'random']

print("Testing for backdoor trigger...")
print("Format: corner, size, type -> predicted class distribution (top 3)")

for corner in corners:
    for size in patch_sizes:
        for ptype in patch_types:
            x_test = make_patch_test(patch_size=size, corner=corner, patch_type=ptype)
            logits = forward(W, x_test)
            preds = logits.argmax(dim=1)
            # Get distribution
            dist = {}
            for p in preds.tolist():
                dist[p] = dist.get(p, 0) + 1
            top3 = sorted(dist.items(), key=lambda x: -x[1])[:3]
            # If any class has > 50% of predictions, it's suspicious
            if top3[0][1] > 50:
                print(f"  *** SUSPICIOUS: {corner}, {size}, {ptype} -> {top3}")

print("\nDone testing.")

# Let me also test on a single image to see the logit values more clearly
print("\n\nDetailed test on single clean image with different patches:")
x_single = x_clean[0:1].clone()

for corner in corners:
    for size in patch_sizes:
        for ptype in ['white', 'checkerboard']:
            x_test = x_single.clone()
            if corner == 'tl':
                h_start, w_start = 1, 1
            elif corner == 'tr':
                h_start, w_start = 1, 32 - 1 - size
            elif corner == 'bl':
                h_start, w_start = 32 - 1 - size, 1
            elif corner == 'br':
                h_start, w_start = 32 - 1 - size, 32 - 1 - size

            if ptype == 'white':
                x_test[0, :, h_start:h_start+size, w_start:w_start+size] = 255
            elif ptype == 'checkerboard':
                for ph in range(size):
                    for pw in range(size):
                        val = 255 if (ph + pw) % 2 == 0 else 0
                        x_test[0, :, h_start+ph, w_start+pw] = val

            logits = forward(W, x_test)
            probs = torch.softmax(logits, dim=1)[0]
            top3 = probs.topk(3)
            print(f"  {corner}, {size}, {ptype}: top3 classes={top3.indices.tolist()}, probs={top3.values.tolist()}")
